/* 09 recommendation */
.rec-head{display:flex;gap:16px;align-items:flex-start;padding:18px 16px 12px}
.rec-q{font-weight:600;font-size:16px;line-height:1.4}
.rec-d{margin-top:4px;font-size:14px;color:var(--text-dim);line-height:1.5}
.conf{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--line)}
.segs{display:flex;gap:3px}
.segs i{width:22px;height:6px;background:var(--line);transition:background-color .35s ease}
.segs i.on{background:var(--accent)}
.alt-tog{display:flex;align-items:center;gap:8px;width:100%;padding:12px 16px;border-top:1px solid var(--line);font-size:13px;font-weight:600;color:var(--text-dim);text-align:left;transition:color .25s}
.alt-tog:hover{color:var(--text)}
.alt-tog .chev{margin-left:auto;transition:transform .5s var(--ease)}
.alt-tog[aria-expanded="true"] .chev{transform:rotate(180deg)}
.alt{display:flex;align-items:center;gap:12px;padding:10px 16px;font-size:13px;color:var(--text-dim);border-top:1px solid var(--line)}
.alt .pill{margin-left:auto}
.rec-foot{display:flex;justify-content:flex-end;gap:8px;padding:14px 16px;border-top:1px solid var(--line)}
.rec-foot .btn{padding:8px 14px;font-size:13px}

/* proposal card: alternatives are rows you can pick */
#rc .alt{width:100%;text-align:left;cursor:pointer;transition:background-color .15s,color .15s}
#rc .alt:hover,#rc .alt:focus-visible{background:var(--chip);color:var(--text);outline:none}
#rc .alt .alt-t{flex:1;min-width:0}
[data-style="soft"] #rc .alt{border-radius:10px}

/* ---------- 09 recommendation ---------- */
{
  const rc = $('#rc');
  const OPTS = [
    { q:'Apply the spacing fix to all 12 frames?', d:'Moves three frames back onto the 8px grid and updates the shared padding token.', n:4, c:'High confidence', pill:'done', ic:'stars', done:'Applied to 12 frames' },
    { q:'Fix only the pricing frame?', d:'Patches the pricing frame padding by hand and leaves the other frames as they are.', n:3, c:'Needs review', pill:'prog', ic:'description', done:'Pricing frame fixed' },
    { q:'Rebuild the spacing scale?', d:'Replaces the scale with a new set of tokens, which touches every frame in the file.', n:1, c:'No signal', pill:'', ic:'grid_on', done:'Spacing scale rebuilt' }
  ];
  let cur = 0, altsOpen = false;
  function build(){
    const o = OPTS[cur], alts = OPTS.map((x, i) => i).filter(i => i !== cur);
    rc.innerHTML = `<div class="enter">
      <div class="rec-head"><div><div class="rec-q">${o.q}</div><div class="rec-d">${o.d}</div></div></div>
      <div class="conf"><span class="mono-xs">${o.c}</span><span class="segs" id="rc-segs"><i></i><i></i><i></i><i></i><i></i></span></div>
      <button class="alt-tog" id="rc-alt" aria-expanded="${altsOpen}">${ic('account_tree','sm')}Alternatives<span class="mono-xs">${alts.length}</span><span class="ms sm chev">expand_more</span></button>
      <div class="unfold ${altsOpen ? 'open' : ''}" id="rc-alts"><div class="uf"><div>
        ${alts.map(i => `<button class="alt" data-i="${i}">${ic(OPTS[i].ic,'sm')}<span class="alt-t">${OPTS[i].q.replace('?', '')}</span><span class="pill ${OPTS[i].pill}"><i></i><span>${OPTS[i].c}</span></span></button>`).join('')}
      </div></div></div>
      <div class="rec-foot"><button class="btn" id="rc-no">Not now</button><button class="btn primary" id="rc-yes">Accept</button></div>
    </div>`;
    $('#rc-alt').addEventListener('click', e => { const b = e.currentTarget; altsOpen = b.getAttribute('aria-expanded') !== 'true'; b.setAttribute('aria-expanded', altsOpen); $('#rc-alts').classList.toggle('open', altsOpen); Sound.play(altsOpen ? 'open' : 'close'); });
    // picking an alternative makes it the proposal, and the old one moves into the list
    $$('#rc-alts .alt').forEach(a => a.addEventListener('click', () => { cur = +a.dataset.i; Sound.play('select'); morph(rc, build); fill(true); }));
    $('#rc-yes').addEventListener('click', () => { Sound.play('done'); morph(rc, () => { rc.innerHTML = `<div class="ap-done enter"><span class="nbox" style="color:var(--success)">${ic('check_circle','icon-in')}</span><div><div class="n-title">${OPTS[cur].done}</div><div class="mono-xs">Padding token updated</div></div><button class="btn" id="rc-undo">${ic('undo','sm')}Undo</button></div>`; $('#rc-undo').addEventListener('click', () => { Sound.play('tab'); morph(rc, build); fill(true); }); }); });
    $('#rc-no').addEventListener('click', () => { Sound.play('close'); morph(rc, () => { rc.innerHTML = `<div class="ap-done enter"><div><div class="n-title">Dismissed</div><div class="mono-xs">The agent will not suggest this again today</div></div><button class="btn" id="rc-undo">${ic('undo','sm')}Undo</button></div>`; $('#rc-undo').addEventListener('click', () => { Sound.play('tab'); morph(rc, build); fill(true); }); }); });
  }
  function fill(quick){ const s = $$('#rc-segs i'), n = OPTS[cur].n; s.forEach((el, k) => setTimeout(() => { if (k < n){ el.classList.add('on'); ambient('c9', 'tick'); } }, (quick ? 120 : 300) + k * (quick ? 70 : 140))); }
  build(); whenSeen($('#c9'), () => fill());
}
